INSERT INTO `home_config` (`id`, `titulo_hero`, `subtitulo_hero`, `atualizado_por`, `updated_at`, `texto_sobre`, `visivel_sobre`, `nome_empresa`, `visivel_nome_empresa`, `endereco`, `visivel_endereco`, `telefone`, `visivel_telefone`, `facebook_url`, `visivel_facebook`, `instagram_url`, `visivel_instagram`, `align_titulo_hero`, `align_subtitulo_hero`) VALUES
('f4b07b29-70ae-4292-8d53-7084b19c0f23', 'O MELHOR RODÍZIO DE PIZZA PARA SEU EVENTO!', 'Há anos levando o melhor sabor da pizza artesanal para Londrina e região. Ingredientes frescos, massa artesanal e muito amor em cada fatia.', NULL, '2026-04-15T16:19:17.389+00:00', 'Julios Pizzas House iniciou suas atividades em 2018 e hoje é uma referência no rodízio de pizzas fazendo a melhor pizza de Londrina Pr. Buscando sempre manter um alto padrão de qualidade visando sempre à satisfação dos nossos clientes.\n\nTodo o processo é rigorosamente acompanhado por mim Julio e minha Equipe, garantindo um atendimento com alto padrão de qualidade.\n\nPrezamos pela comodidade e satisfação dos nossos clientes.\n\nTemos uma vasta experiência em eventos corporativos, com toda estrutura própria e com funcionários constantemente treinados.\n\nFaça o seu rodízio de pizzas sem sair do conforto de sua casa com Julio House Pizza.', TRUE, 'Júlio\'s Pizza House', TRUE, 'Londrina - PR', TRUE, '(43) 99126-7766', TRUE, 'https://www.facebook.com/JuliosPIZZAHOUSE/', TRUE, 'https://instagram.com/juliospizzahouse', TRUE, 'center', 'center');
